INSERT INTO `bib_id_aytst_texts` (`id`, `text`, `title`) VALUES
(1, 'Pada mulanya <07225>, Allah <0430> menciptakan <01254> langit <08064> dan bumi <0776>. [<0853> <0853>]', 'Permulaan Penciptaan'),
(2, 'Bumi <0776> tidak berbentuk <08414> dan kosong <0922>, kegelapan <02822> menutupi <05921> permukaan <06440> samudra <08415>, dan Roh <07307> Allah <0430> melayang-layang <07363> di atas <05921> permukaan <06440> air <04325>. [<01961>]', ''),
(3, 'Kemudian, Allah <0430> berfirman <0559>, “Jadilah <01961> terang <0216>.” Lalu, terang <0216> itu jadi <01961>.', ''),
(4, 'Allah <0430> melihat <07200> bahwa <03588> terang <0216> itu baik <02896>. Kemudian, Allah <0430> memisahkan <0914> terang <0216> itu dari <0996> gelap <02822>. [<0853> <0996>]', ''),
(5, 'Allah <0430> menyebut <07121> terang <0216> itu siang <03117> dan gelap <02822> itu malam <03915>. Jadilah <01961> petang <06153> dan jadilah <01961> pagi <01242>, itulah hari <03117> pertama <0259>. [<07121> <00>]', ''),
(6, 'Kemudian, Allah <0430> berfirman <0559>, “Jadilah <01961> cakrawala <07549> di tengah-tengah <08432> air <04325> untuk memisahkan <0914> air <04325> dari <0996> air <04325>!” [<01961>]', ''),
(7, 'Lalu, Allah <0430> membuat <06213> cakrawala <07549> dan memisahkan <0914> air <04325> yang <0834> ada di atas <08478> cakrawala <07549> itu dari <0996> air <04325> yang <0834> ada di bawah <05921> cakrawala <07549> itu. Lalu, jadilah <01961> demikian <03651>. [<0853> <0996>]', ''),
(8, 'Allah <0430> menyebut <07121> cakrawala <07549> itu langit <08064>. Jadilah <01961> petang <06153> dan jadilah <01961> pagi <01242>, itulah hari <03117> kedua <08145>. [<00>]', ''),
(9, 'Kemudian, Allah <0430> berfirman <0559>, “Biarlah air <04325> yang ada di bawah <08478> langit <08064> berkumpul <06960> ke <0413> satu <0259> tempat <04725> dan biarlah tanah yang kering <03004> itu tampak <07200>.” Lalu, jadilah <01961> demikian <03651>.', ''),
(10, 'Allah <0430> menyebut <07121> tanah yang kering <03004> itu darat <0776> dan kumpulan <04723> air <04325> itu disebut-Nya <07121> laut <03220>. Allah <0430> melihat <07200> bahwa <03588> itu baik <02896>.', ''),
(11, 'Allah <0430> berfirman <0559>, “Biarlah bumi <0776> menumbuhkan <01876> rerumputan <01877>, tumbuh-tumbuhan <06212> berbiji <02232> <02233>, dan pohon <06086> buah <06529> yang berbuah <06213> <06529> menurut jenisnya <04327> dan berbiji <02233> di dalamnya, di atas <05921> bumi <0776>.” Lalu, jadilah <01961> demikian <03651>. [<0834> <00>]', ''),
(12, 'Bumi <0776> menumbuhkan <03318> rerumputan <01877>, tumbuh-tumbuhan <06212> berbiji <02232> <02233> menurut jenisnya <04327>, dan pohon <06086> yang berbuah <06213> <06529> dengan <0834> biji <02233> di dalamnya menurut jenisnya <04327>. Allah <0430> melihat <07200> bahwa <03588> itu baik <02896>. [<00>]', ''),
(13, 'Jadilah <01961> petang <06153> dan jadilah <01961> pagi <01242>, itulah hari <03117> ketiga <07992>. [<00>]', ''),
(14, 'Kemudian, Allah <0430> berfirman <0559>, “Biarlah ada <01961> penerang <03974> di cakrawala <07549> langit <08064> untuk memisahkan <0914> siang <03117> dari <0996> malam <03915>, dan biarlah <01961> <0> itu ada <0> <01961> untuk tanda-tanda <0226> dan untuk musim-musim <04150>, dan untuk hari-hari <03117> serta tahun-tahun <08141>, [<0996>]', ''),
(15, 'dan biarlah <01961> itu menjadi penerang <02974> di cakrawala <07549> langit <08064>, untuk memberikan terang <0215> atas <05921> bumi <0776>.” Demikianlah <03651> itu terjadi <01961>.', ''),
(16, 'Allah <0430> membuat <06213> dua <08147> penerang <03974> yang besar <01419>. Penerang <03974> yang lebih besar <01419> untuk menguasai <04475> siang <03117>, sedangkan penerang <03974> yang lebih kecil <06996> untuk menguasai <04475> malam <03915>. Dia juga membuat bintang-bintang <03556>. [<0853> <0853> <0853> <0853>]', ''),
(17, 'Allah <0430> mengatur <05414> mereka di cakrawala <07549> langit <08064> untuk menerangi <0215> bumi <0776>, [<0853> <05921>]', ''),
(18, 'untuk menguasai <04910> siang <03117> dan menguasai malam <03915>, dan untuk memisahkan <0914> terang <0216> dari <0996> gelap <02822>. Allah <0430> melihat <07200> bahwa <03588> itu baik <02896>. [<0996>]', ''),
(19, 'Jadilah <01961> petang <06153> dan jadilah <01961> pagi <01242>, itulah hari <03117> keempat <07243>. [<00>]', ''),
(20, 'Kemudian, Allah <0430> berfirman <0559>, “Biarlah air <04325> dikerumuni <08317> oleh makhluk-makhluk <05315> hidup <02416>, dan biarlah burung-burung <05775> beterbangan <05774> di atas <05921> bumi <0776>, melintasi <05921> <06440> cakrawala <07549> langit <08064>.” [<08318>]', ''),
(21, 'Lalu, Allah <0430> menciptakan <01254> binatang-binatang laut <08577> yang besar <01419> dan segala <03605> jenis makhluk <05315> hidup <02416> yang <0834> bergerak <07430> serta berkerumun <08317> di dalam air <04325> menurut jenisnya <04327>, dan segala <03605> burung <05775> bersayap <03671> menurut jenisnya <04327>. Allah <0430> melihat <07200> bahwa <03588> itu baik <02896>. [<0853> <0853> <0853>]', ''),
(22, 'Allah <0430> memberkatinya <01288>, firman-Nya <0559>, “Berkembangbiaklah <06509>, dan berlipatgandalah <07235>, dan penuhilah <04390> air <04325> di lautan <03220>, dan biarlah burung-burung <05775> berlipat ganda <07235> di bumi <0776>.” [<0853> <0853>]', ''),
(23, 'Jadilah <01961> petang <06153> dan jadilah <01961> pagi <01242>. Inilah hari <03117> kelima <02549>. [<00>]', ''),
(24, 'Kemudian, Allah <0430> berfirman <0559>, “Biarlah bumi <0776> menghasilkan <03318> makhluk <05315> hidup <02416> menurut jenisnya <04327>, hewan ternak <0929>, binatang melata <07431>, dan binatang-binatang liar <02416>, masing-masing menurut jenisnya <04327>.” Lalu, jadilah <01961> demikian <03651>. [<0776>]', ''),
(25, 'Allah <0430> membuat <06213> binatang liar <02416> di darat <0776> itu menurut jenisnya <04327>, hewan ternak <0929> menurut jenisnya <04327>, dan segala <03605> binatang melata <07431> di atas tanah <0127> menurut jenisnya <04327>. Allah <0430> melihat <07200> bahwa <03588> itu baik <02896>. [<0853> <0853> <0853>]', ''),
(26, 'Kemudian, Allah <0430> berfirman <0559>, “Sekarang, mari Kita membuat <06213> manusia <0120> dalam rupa <06754> Kita, menurut keserupaan <01823> Kita. Biarlah mereka berkuasa <07287> atas ikan-ikan <01710> di laut <03220>, atas burung-burung <05775> di udara <08064>, atas ternak <0929>, atas seluruh <03605> bumi <0776>, dan atas segala <03605> yang melata <07431> yang merayap <07430> di <05921> bumi <0776>.”', ''),
(27, 'Lalu, Allah <0430> menciptakan <01254> manusia <0120> menurut rupa-Nya <06754>. Menurut rupa <06754> Allah <0430>, Dia menciptakannya <01254>. Laki-laki <02145> dan perempuan <05347>, demikianlah Dia menciptakan <01254> mereka. [<0853> <0853> <0853>]', ''),
(28, 'Allah <0430> memberkati <01288> mereka dan Allah <0430> berfirman <0559> kepada mereka, “Beranakcuculah <06509> dan berlipatgandalah <07235>, dan penuhilah <04390> bumi <0776>, dan kuasailah <03533> itu. Berkuasalah <07287> atas ikan-ikan <01710> di laut <03220>, atas burung-burung <05775> di udara <08064>, dan atas segala <03605> yang hidup <02416> yang bergerak <07430> di <05921> bumi <0776>.” [<0853> <00> <0853>]', ''),
(29, 'Kemudian, Allah <0430> berfirman <0559>, “Lihat <02009>, Aku telah memberikan <05414> kepadamu segala <03605> tumbuhan <06212> yang menghasilkan <02232> biji <02233> yang <0834> ada di <05921> seluruh <03605> muka <06440> bumi <0776>, dan segala <03605> pohon <06086> yang <0834> buahnya <06529> berbiji <02232> <02233>, itulah yang akan menjadi <01961> makananmu <0402>. [<00> <0853> <0853> <00> <06086> <00>]', ''),
(30, 'Untuk segala <03605> binatang <02416> di bumi <0776>, dan untuk segala <03605> burung <05775> di langit <08064>, dan untuk segala <03605> yang merayap <07430> di <05921> bumi <0776>, yaitu segala sesuatu ada napas hidup <05315> <02416> di dalamnya, Aku telah memberi segala <03605> tumbuhan <06212> hijau <03418> sebagai makanan <0402>.” Lalu, jadilah <01961> demikian <03651>. [<0834> <00> <0853>]', ''),
(31, 'Allah <0430> mengamati <07200> segala sesuatu <03605> yang <0834> telah dibuat-Nya <06213>, dan lihatlah <02009>, itu sangat <03966> baik <02896>! Jadilah <01961> petang <06153> dan jadilah <01961> pagi <01242>. Inilah hari <03117> keenam <08345>. [<0853> <00>]', ''),
(32, 'Demikianlah langit <08064> dan bumi <0776> beserta segala <03605> isinya <06635> diselesaikan <03615>.', ''),
(33, 'Pada hari <03117> ketujuh <07637>, Allah <0430> menyelesaikan <03615> pekerjaan-Nya <04399>, yang <0834> telah dilakukan-Nya <06213> itu, dan Dia beristirahat <07673> pada hari <03117> ketujuh <07637> dari segala <03605> pekerjaan-Nya <04399>, yang <0834> telah dilakukan-Nya <06213>.', ''),
(34, 'Lalu, Allah <0430> memberkati <01288> hari <03117> ketujuh <07637> itu dan menguduskannya <06942>, sebab <03588> pada saat itu, Dia beristirahat <07673> dari segala <03605> pekerjaan-Nya <04399>, yang <0834> telah dilakukan-Nya <0430> <06213> dalam penciptaan <01254>. [<0853> <0853> <00> <00>]', ''),
(35, 'Inilah <0428> riwayat <08435> langit <08064> dan bumi <0776> ketika mereka diciptakan <01254>, pada waktu <03117> TUHAN <03068> Allah <0430> menjadikan <06213> bumi <0776> dan langit <08064>,', 'Permulaan Umat Manusia'),
(36, 'ketika di bumi <0776> belum <02962> ada <01961> segala <03605> semak belukar <07880> di ladang <07704> dan belum <02962> ada tanaman <06212> ladang <07704> yang tumbuh <06779> karena <03588> TUHAN <03068> Allah <0430> belum <03808> menurunkan hujan <04305> ke <05921> bumi <0776>, dan belum ada <0369> orang <0120> yang mengolah <05647> tanah <0127> itu. [<03605> <0853>]', ''),
(37, 'Namun, ada kabut <0108> yang keluar <05927> dari <04480> bumi <0776> dan membasahi <08248> seluruh <03605> permukaan <06440> bumi <0127>. [<0853>]', ''),
(38, 'Kemudian, TUHAN <03068> Allah <0430> membentuk <03335> manusia <0120> dari <04480> debu <06083> tanah <0127> dan mengembuskan <05301> napas <05397> kehidupan <02416> ke dalam lubang hidungnya <0639> sehingga manusia <0120> itu menjadi <01961> makhluk <05315> yang hidup <02416>. [<0853>]', ''),
(39, 'Lalu, TUHAN <03068> Allah <0430> membuat <05193> sebuah taman <01588> di sebelah timur <06924>, di Eden <05731>, dan di sana <08033> Dia menempatkan <07760> manusia <0120> yang <0834> telah dibentuk-Nya <03335> itu. [<0853>]', ''),
(40, 'Dari <04480> dalam tanah <0127>, TUHAN <03068> Allah <0430> menumbuhkan <06779> segala jenis <03605> pohon <06086> yang enak <02530> dilihat <04758> dan baik <02896> untuk makanan <03978>. Pohon <06086> kehidupan <02416> juga ada di tengah-tengah <08432> taman <01588> itu beserta pohon <06086> pengetahuan <01847> yang baik <02896> dan yang jahat <07451>.', ''),
(41, 'Ada suatu sungai <05104> yang mengalir dari <03318> Eden <05731> dan mengairi <08248> taman <01588> itu. Dari situ <08033>, sungai tersebut terbagi <06504> menjadi <01961> empat <0702> cabang <07218>. [<0853>]', ''),
(42, 'Nama <08034> sungai yang pertama <0259> adalah Pison <06376> yang mengelilingi <05437> seluruh <03605> tanah <0776> Hawila <02341>, tempat <08033> yang ada emasnya <02091>. [<01931> <0853> <0834>]', ''),
(43, 'Emas <02091> dari tanah <0776> itu <01931> bagus <02896>, dan di sana <08033> ada damar bedolah <0916> dan batu <068> krisopras <07718>.', ''),
(44, 'Nama <08034> sungai <05104> yang kedua <08145> adalah Gihon <01521> yang mengalir mengelilingi <05437> seluruh <03605> tanah <0776> Kush <03568>. [<01931> <0853>]', ''),
(45, 'Nama <08034> sungai <05104> yang ketiga <07992> adalah Tigris <02313> yang mengalir <01980> di sebelah timur <06926> Asyur <0804>. Sungai <05104> yang keempat <07243> adalah Efrat <06578>. [<01931> <01931>]', ''),
(46, 'TUHAN <03068> Allah <0430> mengambil <03947> manusia <0120> itu dan menempatkannya <03240> di taman <01588> Eden <05731> untuk mengolahnya <05647> dan memeliharanya <08104>. [<0853>]', ''),
(47, 'Kemudian, TUHAN <03068> Allah <0430> memberikan perintah <06680> kepada <05921> manusia <0120> itu, firman-Nya <0559>, “Kamu boleh makan <0398> <0398> dari segala <03605> pohon <06086> apa yang ada di taman <01588> ini,', ''),
(48, 'tetapi kamu jangan <03808> makan <0398> dari <04480> pohon <06086> pengetahuan <01847> tentang yang baik <02896> dan yang jahat <07451>, sebab <03588> pada hari <03117> kamu memakannya <0398>, kamu pasti <04191> <0> <04191> <0> akan mati <0> <04191> <0> <04191>.” [<04480>]', ''),
(49, 'Kemudian, TUHAN <03068> Allah <0430> berfirman <0559>, “Tidak <03808> baik <02896> kalau manusia <0120> itu sendiri <0905> saja. Aku akan membuat <06213> baginya, penolong <05828> yang sepadan <05048> dengannya.” [<01961> <00>]', ''),
(50, 'Lalu, dari <04480> tanah <0127>, TUHAN <03068> Allah <0430> membentuk <03335> segala <03605> binatang <02416> di padang <07704> dan segala <03605> burung <05775> di udara <08064>, dan membawanya <0935> kepada <0413> manusia <0120> untuk melihat <07200> bagaimana <04100> dia akan menyebut <07121> mereka. Apa pun <03605> sebutan <07121> manusia <0120> itu bagi setiap makhluk <05315> hidup <02416> itu, itulah <01931> namanya <08034>. [<0853> <00> <0834> <00>]', ''),
(51, 'Jadi, manusia <0120> itu memberikan <07121> nama <08034> untuk semua <03605> hewan <0929>, untuk burung-burung <05775> di udara <08064>, dan semua <03605> binatang liar <02416> di padang <07704>. Akan tetapi, bagi manusia <0120> itu, tidak <03808> ditemukan <04672> seorang penolong <05828> yang sepadan <05048> dengannya.', ''),
(52, 'Lalu, TUHAN <03068> Allah <0430> mendatangkan <05307> tidur yang lelap <08639> atas <05921> manusia <0120> itu. Ketika dia tidur <03462>, TUHAN mengambil <03947> salah satu <0259> tulang rusuknya <06763>, lalu dan menutupnya <05462> dengan <08478> daging <01320>.', ''),
(53, 'Tulang rusuk <06763>, yang <0834> telah TUHAN <03068> Allah <0430> ambil <03947> dari <04480> manusia <0120> itu, dibuat-Nya <01129> menjadi seorang perempuan <0802> dan dibawa-Nya <0935> kepada <0413> manusia <0120> itu. [<0853>]', ''),
(54, 'Kemudian, manusia <0120> itu berkata <0559>, “Inilah <02063> tulang <06106> dari tulang-tulangku <06106>, dan daging <01320> dari dagingku <01320>; dia <02063> akan disebut <07121> perempuan <0802> karena <03588> dia <02063> diambil <03947> dari laki-laki <0376>.” [<06471>]', ''),
(55, 'Karena <05921> itu <03651>, laki-laki <0376> akan meninggalkan <05800> ayahnya <01> dan ibunya <0517>, lalu bersatu <01692> dengan istrinya <0802> sehingga mereka akan menjadi <01961> satu <0259> daging <01320>. [<0853> <0853>]', ''),
(56, 'Manusia <0120> dan istrinya <0802> itu, keduanya <08147> telanjang <06174>, tetapi mereka tidak <03808> merasa malu <0954>. [<01961>]', ''),
(57, 'Ular <05175> adalah <01961> yang paling licik <06175> dari segala <03605> binatang <02416> di padang <07704> yang <0834> telah dijadikan <06213> oleh TUHAN <03068> Allah <0430>. Dia berkata <0559> kepada <0413> perempuan <0802> itu, “Apakah <0637> Allah <0430> benar-benar berfirman <0559>, ‘Kamu tidak boleh <03808> makan <0398> dari pohon <06086> mana pun <03605> di taman <01588> ini?’”', 'Permulaan Dosa'),
(58, 'Perempuan <0802> itu berkata <0559> kepada <0413> ular <05175>, “Kami boleh makan buah <06529> dari pohon-pohon <06086> dalam taman <01588>, [<0398>]', ''),
(59, 'tetapi dari buah <06529> pohon <06086> yang <0834> ada di tengah <08432> taman <01588>, Allah <0430> telah berfirman <0559>, ‘Kamu tidak <03808> boleh memakannya <0398>, kamu juga tidak <03808> boleh menyentuhnya <05060>, jangan <06435> sampai kamu mati <04191>.’” [<04480> <00>]', ''),
(60, 'Namun, ular <05175> itu berkata <0559> kepada <0413> perempuan <0802> itu, “Kamu sama sekali tidak <03808> akan mati <04191>, [<04191>]', ''),
(61, 'sebab <03588> Allah <0430> tahu <03045> bahwa <03588> pada hari <03117> kamu memakannya <0398>, matamu <05869> akan terbuka <06491> dan kamu akan menjadi <01961> seperti Allah <0430>, tahu <03045> yang baik <02896> dan yang jahat <07451>!” [<04480>]', ''),
(62, 'Ketika perempuan <0802> itu melihat <07200> bahwa <03588> pohon <06086> itu baik <02896> untuk makanan <03978> dan itu <03588> menarik bagi <01931> mata <05869>, dan pohon <06086> itu diinginkan <08378> untuk membuat seseorang bijaksana <07919>, dia pun memetik buahnya <06529> dan memakannya <0398>, dan dia juga <01571> memberikannya <05414> kepada suaminya <0582> yang bersamanya <05973>, dia memakannya <0398>. [<02530> <03947>]', ''),
(63, 'Lalu, mata <05869> mereka berdua <08147> terbuka <06491> sehingga mereka tahu <03045> bahwa <03588> mereka telanjang <05903>. Kemudian, mereka <01992> menyemat <08609> daun-daun <05929> ara <08384> dan membuat <06213> cawat <02290>. [<00>]', ''),
(64, 'Ketika mereka mendengar <08085> suara <06963> TUHAN <03068> Allah <0430> yang berjalan <01980> di taman <01588> pada suatu hari <03117> yang sejuk <07307>, manusia <0120> dan istrinya <0802> itu menyembunyikan diri <02244> mereka dari hadapan <06440> TUHAN <03068> Allah <0430>, di antara <08432> pohon-pohon <06086> di dalam taman <01588>. [<0853>]', ''),
(65, 'Namun, TUHAN <03068> Allah <0430> memanggil <07121> <0413> manusia <0120> itu dan berkata <0559> kepadanya <00>, “Di manakah <0335> kamu?”', ''),
(66, 'Dia menjawab <0559>, “Aku mendengar <08085> suara-Mu <06963> di taman <01588> dan aku takut <03372> karena <03588> aku telanjang <05903>, jadi aku <0595> bersembunyi <02244>.” [<0853>]', ''),
(67, 'Kemudian, TUHAN berkata <0559>, “Siapa <04310> yang memberitahukanmu <05046> kalau <03588> kamu telanjang <05903>? Apakah kamu <0859> makan <0398> dari <04480> pohon <06086> yang <0834> kepadamu telah Kuperintahkan <06680> jangan <01115> kamu memakannya <0398>?” [<00> <04480>]', ''),
(68, 'Manusia <0120> itu berkata <0559>, “Perempuan <0802> yang <0834> Engkau berikan <05414> untuk bersamaku <05978> itu, dialah <01931> yang telah memberikannya <05414> kepadaku <00> dari <04480> pohon <06086> itu, maka aku pun memakannya <0398>.”', ''),
(69, 'Lalu, TUHAN <03068> Allah <0430> berkata <0559> kepada perempuan <0802> itu, “Apa <04100> yang <02063> telah kaulakukan <06213>?” Perempuan <0802> itu menjawab <0559>, “Ular <05175> itu menipuku <05377>, maka aku makan <0398>.”', ''),
(70, 'Kemudian, TUHAN <03068> Allah <0430> berkata <0559> kepada <0413> ular <05175> itu, “Karena <03588> kamu telah melakukan <06213> hal ini <02063>, terkutuklah <0779> kamu <0859> di antara segala <03605> hewan ternak <0929>, dan di antara segala <03605> binatang <02416> liar <07704> di padang. Dengan <05921> perutmu <01512>, kamu akan berjalan <01980>, dan kamu akan makan <0398> debu <06083> tanah seumur <03117> hidupmu <02416>. [<03605>]', ''),
(71, 'Aku akan mengadakan permusuhan <0342> antara <0996> kamu dengan <0996> perempuan <0802> ini, dan di antara <0996> keturunanmu <02233> dan <0996> keturunannya <02233>. Keturunannya akan <01931> meremukkan <07779> kepalamu <07218>, dan kamu <0859> akan meremukkan <07779> tumitnya <06119>.” [<07896> <00>]', ''),
(72, 'Kepada <0413> perempuan <0802> itu, Allah berfirman <0559>, “Aku akan sangat <07235> melipatgandakan <07235> susah <06093> payahmu ketika mengandung <02032>; dalam kesakitan <06089> kamu akan melahirkan <03205> anak-anak <01121>; tetapi kamu tetap akan berahi <08669> kepada <0413> suamimu, dan dia <01931> akan berkuasa <04910> atasmu.” [<0376> <00> <00>]', ''),
(73, 'Lalu, kepada manusia <0121> itu, Dia berfirman <0559>, “Karena <03588> kamu mendengarkan <08085> suara <06963> istrimu <0802>, dan telah makan <0398> dari <04480> pohon <06086> yang <0834> kepadamu telah Kuperintahkan <06680>, ‘Jangan <03808> kamu memakannya <0398>,’ terkutuklah <0779> tanah <0127> karena <05668> kamu! Dengan susah payah <06093> kamu akan makan <0398> dari <04480> hasilnya selama hari-hari <03117> hidupmu <02416>. [<0559> <03605>]', ''),
(74, 'Semak duri <06975> dan rumput liarlah <01863> yang akan ditumbuhkan <06779> bagimu, dan kamu akan memakan <0398> tumbuh-tumbuhan <06212> di padang <07704>. [<00> <0853>]', ''),
(75, 'Dengan keringat <02188> di wajahmu <0639>, kamu akan makan <0398> roti <03899>, sampai <05704> kamu kembali <07725> kepada <0413> tanah <0127> yang <03588> darinya <04480> kamu diambil <03947>. Sebab <03588>, kamu adalah debu <06083>, dan kamu <0859> akan kembali <07725> kepada <0413> debu <06083>.', ''),
(76, 'Manusia <0120> itu menyebut <07121> <08034> istrinya <0802> Hawa <02332> karena <03588> dia <01931> adalah <01961> ibu <0517> dari semua <03605> yang hidup <02416>.', ''),
(77, 'TUHAN <03068> Allah <0430> membuat pakaian <03801> dari kulit <05785> untuk manusia <0120> dan istrinya <0802> itu, lalu mengenakannya <03847> kepada mereka <00>. [<06213>]', ''),
(78, 'Setelah itu, TUHAN <03068> Allah <0430> berfirman <0559>, “Lihatlah <02005>, manusia <0120> itu menjadi <01961> seperti salah satu <0259> dari <04480> Kita, tahu <03045> tentang yang baik <02896> dan yang jahat <07451>. Sekarang <06258>, jangan <06435> sampai dia mengulurkan <07971> tangannya <03027> dan mengambil <03947> juga <01571> dari pohon <06086> kehidupan <02416>, lalu memakannya <0398> dan hidup <02425> selama-lamanya <05769>.”', ''),
(79, 'Karena itu, TUHAN <03068> Allah <0430> menyuruhnya <07971> keluar dari taman <01588> Eden <05731> untuk mengolah <05647> tanah <0127> yang <0834> dari itu dia diambil <03947>. [<0853> <08033>]', ''),
(80, 'Setelah Allah menghalau <01644> manusia <0120> itu keluar, di sebelah timur <06924> taman <01588> Eden <05731> ditempatkan-Nyalah <07931> kerub-kerub <03742> dengan pedang <02719> api <03858> yang menyambar-nyambar <02015> untuk menjaga <08104> jalan <01870> menuju pohon <06086> kehidupan <02416>. [<0853> <0853> <0853> <0853> <00>]', ''),
(81, 'Adam bersetubuh <03045> dengan Hawa <02332>, istrinya <0802>, lalu Hawa mengandung <02029> dan melahirkan <03205> Kain <07014>. Dia berkata <0559>, “Aku telah <07069> mendapatkan seorang laki-laki <0376> dari <0854> TUHAN <03068>!” [<0120> <0853> <0853>]', 'Kain dan Habel'),
(82, 'Kemudian, Hawa melahirkan <03205> adiknya <0251>, yaitu <0853> Habel <01893>. Habel <01893> menggembalakan <07462> domba <06629>, sedangkan Kain <07014> menggarap <05647> tanah <0127>. [<03254> <0853> <01961> <01961>]', ''),
(83, 'Pada <01961> suatu waktu <03117>, Kain <07014> membawa <0935> kepada TUHAN <03068> suatu persembahan <04503> hasil <06529> dari tanah <0127> itu, [<07093>]', ''),
(84, 'Habel <01893> juga <01571> membawa <0935> yang sulung <01062> dari kawanan dombanya <06629> beserta lemak-lemaknya <02459>. TUHAN <03068> memperhatikan <08159> Habel <01893> dan <0413> persembahannya <04503>, [<01931> <0413>]', ''),
(85, 'tetapi terhadap <0413> Kain <07014> dan <0413> persembahannya <04503>, Dia tidak <03808> memperhatikannya <08159>. Lalu, Kain <07014> menjadi sangat <03966> marah <02734> dan wajahnya <06440> muram <05307>.', ''),
(86, 'TUHAN <03068> berkata <0559> kepada <0413> Kain <07014>, “Mengapa <04100> kamu marah <02734>? Mengapa <04100> mukamu <06440> muram <05307>? [<00>]', ''),
(87, 'Jika <0518> kamu berbuat baik <03190>, bukankah <03808> kamu akan diterima <07613>? Namun, jika <0518> kamu tidak <03808> berbuat baik <03190>, dosa <02403> sudah mengintip <07257> di <0413> pintu <06607>, keinginannya <08669> adalah untukmu, tetapi kamu <0859> harus berkuasa <04910> atasnya.” [<00>]', ''),
(88, 'Kain <07014> berbicara dengan <0413> Habel <01893>, saudaranya <0251>. Lalu, terjadilah <01961>, ketika mereka berada <01961> di padang <07704>, Kain <07014> bangkit <06965> untuk menyerang <0413> Habel <01893>, saudaranya <0251> itu, dan membunuhnya <02026>. [<0559>]', ''),
(89, 'Lalu, TUHAN <03068> bertanya <0559> kepada <0413> Kain <07014>, “Di mana <0335> Habel <01893>, adikmu <0251>?” Kain menjawab <0559>, “Aku tidak <03808> tahu <03045>. Apakah aku <0595> penjaga <08104> adikku <0251>?”', ''),
(90, 'TUHAN berkata <0559>, “Apa <04100> yang sudah kamu lakukan <06213>? Suara <06963> darah <01818> adikmu <0251> itu menjerit <06817> kepada-Ku <0413> dari <04480> dalam tanah <0127>.', ''),
(91, 'Sekarang <06258>, kamu <0859> terkutuk <0779> dari <04480> tanah <0127> yang <0834> telah membuka <06475> mulutnya <06310> untuk menerima <03947> darah <01818> adikmu <0251> dari tanganmu <03027>. [<0853> <0853>]', ''),
(92, 'Jika <03588> kamu menggarap <05647> tanah <0127> itu, ia tidak <03808> akan lagi <03254> memberikan <05414> hasilnya <03581> untukmu <00>. Kamu akan mengembara <05128> dan menggelandang <05110> di bumi <0776>.” [<0853> <01961>]', ''),
(93, 'Kemudian, Kain <07014> berkata <0559> kepada <0413> TUHAN <03068>, “Hukumanku <05771> itu lebih berat <01419> daripada yang sanggup kutanggung <05375>.', ''),
(94, 'Lihat <02005>! Hari ini <03117> Engkau telah menggiring <01644> aku dari <05921> tanah <0127> ini. Lalu, aku akan tersembunyi <05641> dari hadapan-Mu <06440>, dan aku akan menjadi <01961> buronan <05128> dan pengembara <05110> di bumi <0776>, dan akan terjadi <01961>, siapa saja <03605> yang bertemu <04672> denganku akan membunuhku <02026>.” [<0853> <06440>]', ''),
(95, 'Namun, TUHAN <03068> berkata <0559> kepada Kain, “Karena <03651> itu, siapa pun <03605> yang membunuh <02026> Kain <07014>, kepadanya akan dibalaskan <05358> tujuh kali lipat <07659>.” Kemudian, TUHAN <03068> memberi <07760> tanda <0226> pada Kain <07014> supaya tidak <01115> seorang pun <03605> yang bertemu <04672> dengannya akan membunuhnya <05221>. [<00> <0853>]', ''),
(96, 'Lalu, Kain <07014> pergi <03318> dari hadapan <06440> TUHAN <03068> dan menetap <03427> di tanah <0776> Nod <05113>, sebelah timur <06926> Eden <05731>.', 'Keturunan Kain'),
(97, 'Kain <07014> bersetubuh <03045> dengan istrinya, lalu istrinya <0802> itu mengandung <02029> dan melahirkan <03205> Henokh <02585>. Kain membangun <01129> suatu kota <05892> dan menyebut <07121> nama <08034> kota <05892> itu seperti nama <08034> anaknya <01121>, Henokh <02585>. [<0853> <0853> <01961>]', ''),
(98, 'Bagi Henokh <02585>, lahirlah <03205> Irad <05897>, dan Irad <05897> adalah ayah <03205> Mehuyael <04232>. Mehuyael <04232> adalah ayah <03205> Metusael <04967>, dan Metusael <04967> adalah ayah <03205> Lamekh <03929>. [<0853> <0853> <0853> <0853>]', ''),
(99, 'Lamekh <03929> mengambil <03947> dua <08147> istri <0802> baginya, yang satu <0259> bernama <08034> Ada <05711> dan yang lain <08145> bernama <08034> Zila <06741>. [<00>]', ''),
(100, 'Ada <05711> melahirkan <03205> Yabal <02989> yang adalah <01931> nenek moyang <01> semua yang tinggal <03427> dalam tenda <0168> dan beternak <04735>. [<0853> <01961>]', ''),
(101, 'Saudaranya <0251> bernama <08034> Yubal <03106>, dia <01931> adalah nenek moyang <01> semua <03605> yang memainkan kecapi <03658> dan seruling <05748>. [<01961> <08610>]', ''),
(102, 'Zila <06741> juga <01571> melahirkan <03205> Tubal-Kain <08423>, dia yang menempa <03913> segala <03605> perkakas <02794> dari perunggu <05178> dan besi <01270>. Saudara perempuan <0269> Tubal-Kain <08423> adalah Naama <05279>. [<01931> <0853> <00> <00>]', ''),
(103, 'Lamekh <03929> berkata <0559> kepada kedua istrinya <0802>, “Ada <05711> dan Zila <06741>, dengarlah <08085> suaraku <06963>! Hai istri-istri <0802> Lamekh <03929>, dengarkanlah <0238> perkataanku <0565>! Aku telah membunuh <02026> seorang laki-laki <0582> karena <03588> lukaku <06482>, dan seorang laki-laki muda <03206> karena melukaiku <02250>.', ''),
(104, 'Jika <03588> kepada Kain <07014> dibalaskan <05358> tujuh kali lipat <07659>, kepada Lamekh <03929> dibalaskan 77 <07657> <07651> kali lipat!”', ''),
(105, 'Adam <0121> bersetubuh <03045> lagi <05750> dengan istrinya <0802>, dan istrinya itu melahirkan <03205> anak laki-laki <01121> lainnya, dan menyebut <07121> namanya <08034> Set <08352>, sebab <03588> katanya, “Allah <0430> menentukan <07896> benih <02233> yang lain <0312> bagiku sebagai ganti <08478> Habel <01893> karena <03588> Kain <07014> telah membunuhnya <02026>.” [<0853> <0853> <00>]', 'Kelahiran Set'),
(106, 'Seorang anak <01121> laki-laki juga <01571> lahir <03205> bagi Set <08352>, dan dia menyebut <07121> namanya <08034> Enos <0583>. Pada <0227> masa itulah manusia mulai <02490> memanggil <07121> nama <08034> TUHAN <03068>. [<01931> <0853> <00>]', ''),
(107, 'Inilah <02088> catatan <05612> keturunan <08435> Adam <0121>. Pada hari <03117> Allah <0430> menciptakan <01254> manusia <0120>, Dia membuatnya <06213> dalam keserupaan <01823> dengan Allah <0430>. [<0853>]', 'Keturunan Adam'),
(108, 'Dia menciptakan <01254> mereka, laki-laki <02145> dan perempuan <05347>, dan Dia memberkati <01288> mereka, dan menamai <07121> <08034> mereka manusia <0120>, pada hari <03117> mereka diciptakan <01254>. [<0853> <0853> <00>]', ''),
(109, 'Ketika Adam <0121> hidup selama <02421> 130 <07970> <03967> tahun <08141> dan seorang anak laki-laki lahir <03205> baginya dalam keserupaan <01823> dengannya, menurut rupanya <06754>. Lalu, dia menamainya <07121> <08034> Set <08352>. [<0853>]', ''),
(110, 'Adam <0121> hidup 800 <08083> <03967> tahun <08141> lagi, dan masih ada anak laki-laki <01121> dan anak perempuan <01323> lainnya yang lahir <03205> baginya. [<01961> <03117> <0310> <03205> <0853> <08352>]', ''),
(111, 'Jadi, seluruh <03605> masa <03117> hidup <02416> Adam <0121> adalah <01961> 930 <08672> <03967> <07970> tahun <08141>, kemudian dia mati <04191>. [<0834> <08141> <00>]', ''),
(112, 'Ketika Set <08352> hidup selama <02421> 105 <02568> <03967> tahun <08141>, Enos <0583> lahir <03205> baginya. [<08141> <0853>]', ''),
(113, 'Set <08352> hidup <02421> 807 <07651> <08083> <03967> tahun <08141> lagi setelah <0310> Enos <0583> lahir <03205>, dan masih ada anak laki-laki <01121> dan anak perempuan <01323> lainnya yang lahir <03205> baginya. [<0853> <08141>]', ''),
(114, 'Jadi, seluruh <03605> masa hidup <03117> Set <08352> adalah <01961> 912 <08147> <06240> <08672> <03967> tahun <08141>, kemudian dia mati <04191>. [<08141> <00>]', ''),
(115, 'Ketika Enos <0583> hidup selama <02421> 90 <08673> tahun <08141>, Kenan <07018> lahir <03205> baginya. [<0853>]', ''),
(116, 'Enos <0583> hidup <02421> 815 <02568> <06240> <08083> <03967> tahun <08141> lagi setelah <0310> Kenan <07018> lahir <03205>, dan dia mendapatkan anak laki-laki dan anak perempuan. Masih ada anak laki-laki <01121> dan anak perempuan <01323> lainnya yang lahir <03205> baginya. [<0853> <08141>]', ''),
