(10262, 'Keturunan <01121> Kush <03568> adalah Seba <05434>, Hawila <02341>, Sabta <05454>, Raema <07484>, dan Sabtekha <05455>. Keturunan <01121> Raema <07484> adalah Syeba <07614> dan Dedan <01719>. [<00>]', ''),
(10263, 'Keturunan <03205> <0> Kush <03568> adalah <0> <03205> Nimrod <05248>, yang menjadi <01961> orang perkasa <01368> pertama <02490> di bumi <0776>. [<0853> <01931> <00>]', ''),
(10264, 'Keturunan <03205> Misraim <04714> adalah Ludim <03866>, Anamim <06047>, Lehabim <03853>, Naftuhim <05320>, [<0853> <0853> <0853> <0853>]', ''),
(10265, 'Patrusim <06625>, Kasluhim <03695>, dari merekalah orang Filistin <06430> berasal <03318>, dan Kaftorim <03732>. [<0853> <0853> <0834> <08033> <0853> <00>]', ''),
(10266, 'Keturunan <03205> <0> Kanaan <03667> adalah <0> <03205> Sidon <06721>, anak sulungnya <01060>, dan Het <02845>, [<0853> <0853>]', ''),
(10267, 'juga orang Yebusi <02983>, orang Amori <0567>, orang Girgasi <01622>, [<0853> <0853> <0853>]', ''),
(10268, 'orang Hewi <02340>, orang Arki <06208>, orang Sini <05513>, [<0853> <0853> <0853>]', ''),
(10269, 'orang Arwadi <0721>, orang Semari <06786>, dan orang Hamati <02577>. [<0853> <0853> <0853> <00>]', ''),
